"""Keep standalone upload requirements in sync with the canonical API profile."""
import argparse
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def profiles() -> dict[str, str]:
    api = (ROOT / "backend/requirements-api.txt").read_text(encoding="utf-8")
    space = re.sub(r"(?m)^pydantic[<>=!~][^\n]*$", "pydantic>=2.11.10,<=2.12.5", api)
    return {
        "requirements.txt": "# API profile for repository-root tooling; generated by scripts/sync_deployment_profiles.py.\n" + api,
        "backend/requirements.txt": "# Direct backend-folder upload profile; generated by scripts/sync_deployment_profiles.py.\n# Gradio 6.31 MCP extras require Pydantic <=2.12.5; API/Docker keep the newer floor.\n" + space
        + "\n# Match the packages and extras injected by the Hugging Face Gradio SDK.\ngradio[oauth,mcp]==6.31.0\nspaces==0.51.3\ntorch>=2.6,<=2.13.0\n",
    }

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for name, expected in profiles().items():
        path = ROOT / name
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != expected:
                raise SystemExit(f"Deployment requirements out of sync: {name}")
        else:
            path.write_text(expected, encoding="utf-8")
